		return NodeInfo{}, false
	}
	now := time.Now()
	status := "healthy"
	if now.Sub(lastSeen) > s.staleAfter {
		status = "stale"
	}
	return NodeInfo{
		Node:     node,
		Status:   status,
		LastSeen: lastSeen,
	}, true
}

func (s *Store) Stop() {
	close(s.stopCh)
}
